import{_ as o,o as d,c,aw as l}from"./chunks/framework.DLufY-ao.js";const m=JSON.parse('{"title":"Выражения","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/js/js-regexp/main/use.md","filePath":"wiki/dev-commit/js/js-regexp/main/use.md"}'),i={name:"wiki/dev-commit/js/js-regexp/main/use.md"};function a(t,e,u,r,n,s){return d(),c("div",null,[...e[0]||(e[0]=[l('<h1 id="выражения" tabindex="-1">Выражения <a class="header-anchor" href="#выражения" aria-label="Permalink to &quot;Выражения&quot;">​</a></h1><h2 id="основное" tabindex="-1">Основное <a class="header-anchor" href="#основное" aria-label="Permalink to &quot;Основное&quot;">​</a></h2><ul><li><code>\\d</code> - любая десятичная цифра</li><li><code>\\D</code> - любой символ, кроме десятичной цифры</li></ul><hr><ul><li><code>\\s</code> - любой пробельный символ</li><li><code>\\S</code> - любой непробельный символ</li></ul><hr><ul><li><code>\\w</code> - любой символ, образующий &quot;слово&quot;</li><li><code>\\W</code> - любой символ, не образующий &quot;слово&quot;</li></ul><hr><ul><li><code>\\b</code> - граница слова</li><li><code>\\B</code> - не граница слова</li></ul><hr><ul><li><code>\\A</code>, <code>\\Z</code>, <code>\\z</code> - в JS не поддерживаются, вместо них <code>^</code> и <code>$</code> без флага <code>m</code></li></ul><hr><ul><li><code>[]</code> - символьный класс</li><li><code>()</code> - подмаска</li><li><code>|</code> - разделитель альтернативных масок</li></ul><hr><ul><li><code>{m,n}</code> - квантификатор повтора: min m, max n раз</li></ul><hr><ul><li><code>(?:)</code> - незахватывающая подмаска</li><li><code>(?=x)</code> - положительное утверждение</li><li><code>(?!x)</code> - отрицательное утверждение</li></ul><h2 id="expression-flag" tabindex="-1">Expression Flag <a class="header-anchor" href="#expression-flag" aria-label="Permalink to &quot;Expression Flag&quot;">​</a></h2><ul><li><code>//g</code> - global (все совпадения)</li><li><code>//i</code> - case insensitive (регистронезависимый поиск)</li><li><code>//m</code> - multiline</li><li><code>//u</code> - unicode</li><li><code>//y</code> - sticky</li></ul><h2 id="символы" tabindex="-1">Символы <a class="header-anchor" href="#символы" aria-label="Permalink to &quot;Символы&quot;">​</a></h2><ul><li><code>\\f</code> - символ разрыва страницы</li><li><code>\\t</code> - символ табуляции</li><li><code>\\v</code> - символ вертикальной табуляции</li><li><code>\\r</code> - символ возврата каретки</li><li><code>\\n</code> - символ перевода строки</li><li><code>\\xhh</code> - символ с кодом hh</li><li><code>\\uhhhh</code> - символ юникод с кодом hhhh</li></ul><h2 id="специальные-символы" tabindex="-1">Специальные символы <a class="header-anchor" href="#специальные-символы" aria-label="Permalink to &quot;Специальные символы&quot;">​</a></h2><ul><li><code>\\</code> - для обычных символов - делает их специальными. Например, выражение <code>/s/</code> ищет просто символ &#39;s&#39;. А если поставить <code>\\</code> перед s, то <code>/\\s/</code> уже обозначает пробельный символ. И наоборот, если символ специальный, например <code>*</code>, то <code>\\</code> сделает его просто обычным символом &quot;звездочка&quot;. Например, <code>/a*/</code> ищет 0 или больше подряд идущих символов &#39;a&#39;. Чтобы найти а со звездочкой <code>&#39;a*&#39;</code> - поставим <code>\\</code> перед спец. символом: <code>/a\\*/</code>.</li><li><code>^</code> - начало ввода (или линии, в многострочном режиме); отрицание в <code>[]</code></li><li><code>$</code> - конец ввода (или линии, в многострочном режиме)</li><li><code>*</code> - соответствует предыдущему символу повторенному 0 или более раз. Эквивалентно <code>{0,}</code>. Например, <code>/bo*/</code> соответствует &#39;boooo&#39; в &quot;A ghost booooed&quot; и &#39;b&#39; в &quot;A bird warbled&quot;, но не в &quot;A goat grunted&quot;.</li><li><code>+</code> - соответствует предыдущему символу повторенному 1 или более раз. Эквивалентно <code>{1,}</code>. Например, <code>/a+/</code> соответствует &#39;a&#39; в &quot;candy&quot; и всем символам &#39;a&#39; в &quot;caaaaaaandy&quot;.</li><li><code>?</code> - соответствует предыдущему символу повторенному 0 или 1 раз. Эквивалентно <code>{0,1}</code>.</li><li><code>.</code> - (десятичная точка) соответствует любому символу кроме переноса строки. Например, <code>/.n/</code> соответствует &#39;an&#39; и &#39;on&#39; в &quot;nay, an apple is on the tree&quot;, но не &#39;nay&#39;.</li></ul>',23)])])}const q=o(i,[["render",a]]);export{m as __pageData,q as default};
